import{bV as a,aL as n,u as e,G as p}from"./chunks/framework.DvBUyM1S.js";const o=JSON.parse('{"title":"使用GitHub自建免费小型图床","description":"","frontmatter":{"title":"使用GitHub自建免费小型图床","date":"2021-1-28","permalink":"/pages/d945b5/","categories":[null],"tags":[null]},"headers":[],"relativePath":"06.工具/05.GitHub/06.Github文件转jsdelivr地址.md","filePath":"06.工具/05.GitHub/06.Github文件转jsdelivr地址.md","lastUpdated":1652179217000}'),i={name:"06.工具/05.GitHub/06.Github文件转jsdelivr地址.md"};function l(t,s,r,c,b,d){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="使用github自建免费小型图床" tabindex="-1">使用GitHub自建免费小型图床 <a class="header-anchor" href="#使用github自建免费小型图床" aria-label="Permalink to &quot;使用GitHub自建免费小型图床&quot;">​</a></h1><h2 id="条件限制" tabindex="-1">条件限制 <a class="header-anchor" href="#条件限制" aria-label="Permalink to &quot;条件限制&quot;">​</a></h2><p>GitHub 用来作小型图床完美的选择，但是随着文章图片越来越多，势必超过50M</p><blockquote><p>程序包大小超出了配置的50 MB限制。 两种引用方式：</p></blockquote><ul><li>存入仓库分支里面，直接引用</li><li>创建版本号后，在引用</li></ul><p>在这是不是很好奇，为什么引用要弄成这么麻烦。网上我看过类似教程，他们总是忽略一个关键的原因避而不谈，因为这点也原因差点坑了我。超过50M <code>jsdelivr</code>就无法访问。为了能免费撸羊毛，建议使用发布版本号方案，只要单次版本号的大小不超过50M即可，多次版本号就可以突破50M限制。</p><blockquote><p>程序包大小超出了配置的50 MB限制。</p></blockquote><p>很好奇为什么我会发现这个问题。我作了一个假设，如果仓库存放超多的图片的资源，且能够访问的话，那么这种教程，作为一种免费撸羊毛的手段在中国应该被大佬推荐，不至于到现在还不温不火。终其原因我尝试上传几张超大的图片，就被提示无法访问，分成两次版本号后（单次不超过50M）总大小超过50M却能正常访问。</p><p><strong>1. 直接引用</strong></p><p>格式为：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://cdn.jsdelivr.net/gh/&lt;用户名&gt;/&lt;仓库名&gt;/&lt;文件及路径&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GitHub</span></span>
<span class="line"><span></span></span>
<span class="line"><span>https://github.com/qqlcx5/figure-bed/blob/master/img/20200710230327.jpg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>转成 jsdelivr</span></span>
<span class="line"><span></span></span>
<span class="line"><span>https://cdn.jsdelivr.net/gh/qqlcx5/figure-bed/img/20200710230327.jpg</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>总结：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>github.com\`替换成cdn.jsdelivr.net/gh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/blob/master 删除</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>版本号</strong></p><p>版本号用@符链接。格式：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://cdn.jsdelivr.net/gh/&lt;用户名&gt;/&lt;仓库名&gt;@[版本号]/&lt;文件及路径&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GitHub</span></span>
<span class="line"><span></span></span>
<span class="line"><span>https://github.com/qqlcx5/figure-bed/blob/1.0/img/20200710230327.jpg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>转成 jsdelivr</span></span>
<span class="line"><span></span></span>
<span class="line"><span>https://cdn.jsdelivr.net/gh/qqlcx5/figure-bed@1.0/img/20200710230327.jpg</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>总结：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>github.com\`替换成cdn.jsdelivr.net/gh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/blob/ 替换成 @ </span></span>
<span class="line"><span>注：1.0 创建的版本号</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>已发布的版本不会受到仓库内容变化的影响 如何按版本号引用。链接相对稳定也是我特别推荐的原因。</p>`,23)])])}const h=a(i,[["render",l]]);export{o as __pageData,h as default};
